import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ source for fused batchnorm+GELU, groupnorm, mean+ReLU
cuda_code = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Approximate GELU
__device__ inline float gelu_approx(float x) {
    const float kAlpha = 0.7978845608f;  // sqrt(2/pi)
    const float kGamma = 0.044715f;
    float x3 = x * x * x;
    return 0.5f * x * (1.f + tanhf(kAlpha * (x + kGamma * x3)));
}

// Kernel: Fused BatchNorm + GELU (inference mode, using running stats)
__global__ void bn_gelu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float eps,
    const int batch_size,
    const int num_channels)
{
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = batch_size * num_channels;
    if (idx < total) {
        int c = idx % num_channels;
        float x = input[idx];
        float mean_val = running_mean[c];
        float var_val = running_var[c];
        float w = weight[c];
        float b = bias[c];
        float norm_x = (x - mean_val) / sqrtf(var_val + eps);
        float bn_x = w * norm_x + b;
        output[idx] = gelu_approx(bn_x);
    }
}

torch::Tensor bn_gelu_forward(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps)
{
    auto batch_size = input.size(0);
    auto num_channels = input.size(1);

    auto output = torch::empty_like(input);
    int total = batch_size * num_channels;

    const int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    bn_gelu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        eps,
        batch_size,
        num_channels
    );
    return output;
}

// Kernel: GroupNorm
// Naive implementation: compute mean/var per group per example, then normalize
__global__ void group_norm_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float eps,
    int batch_size,
    int num_channels,
    int num_groups)
{
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = batch_size * num_channels;
    if (idx < total) {
        int b = idx / num_channels;
        int c = idx % num_channels;
        int group_size = num_channels / num_groups;
        int g = c / group_size; // group index

        // Compute mean/var for the group g of batch b
        // naive iteration over group_size channels
        const int cstart = g * group_size;
        const int cend = cstart + group_size;

        // sum & sum of squares
        float mean_val = 0.f;
        float var_val = 0.f;
        for(int cc = cstart; cc < cend; cc++){
            float in_val = input[b * num_channels + cc];
            mean_val += in_val;
            var_val += in_val * in_val;
        }
        mean_val /= group_size;
        var_val = var_val / group_size - mean_val * mean_val;

        // normalize this channel
        float x = input[idx];
        float x_hat = (x - mean_val) / sqrtf(var_val + eps);
        // weight/bias are per-channel
        float w = weight[c];
        float b_ = bias[c];
        output[idx] = w * x_hat + b_;
    }
}

// Kernel: Mean over dim=1 and ReLU
// input shape: (B, C), output shape: (B, 1)
__global__ void mean_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int num_channels)
{
    int b = blockDim.x * blockIdx.x + threadIdx.x;
    if (b < batch_size) {
        // compute mean across channels
        float sum_val = 0.f;
        for(int c = 0; c < num_channels; c++){
            sum_val += input[b * num_channels + c];
        }
        float mean_val = sum_val / (float)num_channels;
        // ReLU
        output[b] = mean_val > 0.f ? mean_val : 0.f;
    }
}

torch::Tensor group_norm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps,
    int num_groups)
{
    auto batch_size = input.size(0);
    auto num_channels = input.size(1);

    auto output = torch::empty_like(input);
    int total = batch_size * num_channels;

    const int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    group_norm_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        eps,
        batch_size,
        num_channels,
        num_groups
    );
    return output;
}

torch::Tensor mean_relu_forward(
    torch::Tensor input)
{
    // input shape: (B, C)
    auto batch_size = input.size(0);
    auto num_channels = input.size(1);

    auto output = torch::empty({batch_size, 1}, torch::dtype(input.dtype()).device(input.device()));

    const int block_size = 256;
    int grid_size = (batch_size + block_size - 1) / block_size;

    mean_relu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_channels
    );
    return output;
}

