# Compile the fused operators
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_header,
    cuda_sources=cuda_code,
    extra_cflags=[],
    extra_ldflags=[],
    functions=[
        "bn_gelu_forward",
        "group_norm_forward",
        "mean_relu_forward"
    ],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model with fused custom CUDA kernels for BatchNorm+GELU, GroupNorm, and Mean+ReLU.
    GEMM remains as nn.Linear.
    """
    def __init__(self, in_features, out_features, num_groups):
        super().__init__()
        # We keep the linear layer as-is
        self.gemm = nn.Linear(in_features, out_features)
        # Create regular BatchNorm to hold parameters (running_mean, running_var, weight, bias)
        self.batch_norm = nn.BatchNorm1d(out_features)
        # Create GroupNorm to hold parameters (weight, bias)
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        self.eps_bn = self.batch_norm.eps
        self.eps_gn = self.group_norm.eps
        self.num_groups = num_groups

    def forward(self, x):
        # GEMM
        x = self.gemm(x)

        # Fused BatchNorm + GELU
        # Using the running stats and parameters from self.batch_norm
        x = fused_ops.bn_gelu_forward(
            x,
            self.batch_norm.running_mean,
            self.batch_norm.running_var,
            self.batch_norm.weight,
            self.batch_norm.bias,
            self.eps_bn
        )

        # Fused GroupNorm (naive) 
        x = fused_ops.group_norm_forward(
            x,
            self.group_norm.weight,
            self.group_norm.bias,
            self.eps_gn,
            self.num_groups
        )

        # Fused Mean + ReLU
        x = fused_ops.mean_relu_forward(x)
        return x
